-- Existing submissions, enrollment status, task timing and assessment data are untouched.
BEGIN;
CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-content-writing-2026","task_number":1,"title":"Editorial Brief","old_instructions":"[[AZ]]\n## Məqsəd\nMövzu və auditoriya seç ;  Oxucunun cavab axtardığı sualları yaz ;  Məqalənin əsas iddiasını müəyyən et.\n\n## Addım-addım icra\n1. Mövzu və auditoriya seç.\n2. Oxucunun cavab axtardığı sualları yaz.\n3. Məqalənin əsas iddiasını müəyyən et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nEditorial brief. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSelect a topic and audience ;  List reader questions ;  Define the article's central claim.\n\n## Step-by-step\n1. Select a topic and audience.\n2. List reader questions.\n3. Define the article's central claim.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nEditorial brief. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMövzu və auditoriya seç ;  Oxucunun cavab axtardığı sualları yaz ;  Məqalənin əsas iddiasını müəyyən et.\n\n[[EN]]\nSelect a topic and audience ;  List reader questions ;  Define the article's central claim.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Editorial Brief\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** 'İlk internship müraciəti' mövzusunda oxucunun 5 sualını və məqalə məqsədini yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-1. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Mövzu və auditoriya seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Oxucunun cavab axtardığı sualları yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Məqalənin əsas iddiasını müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'İlk internship müraciəti' mövzusunda oxucunun 5 sualını və məqalə məqsədini yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Editorial brief. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'İlk internship müraciəti' mövzusunda oxucunun 5 sualını və məqalə məqsədini yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Editorial brief.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Editorial Brief\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Define five reader questions for a first-internship application article.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-1. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Select a topic and audience. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. List reader questions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Define the article's central claim. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Define five reader questions for a first-internship application article. Document what worked and any limitations.\n7. Complete the main artifact: Editorial brief. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDefine five reader questions for a first-internship application article.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Editorial brief.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nEditorial Brief: Mövzu və auditoriya seç. Oxucunun cavab axtardığı sualları yaz. Məqalənin əsas iddiasını müəyyən et. Pulsuz alətlər: Google Docs. Nəticə: Editorial brief.\n\n[[EN]]\nEditorial Brief: Select a topic and audience. List reader questions. Define the article's central claim. Free tools: Google Docs. Output: Editorial brief."},{"slug":"talora-content-writing-2026","task_number":2,"title":"Source Research","old_instructions":"[[AZ]]\n## Məqsəd\nƏn azı beş etibarlı mənbə tap ;  Nəşr tarixlərini yoxla ;  Faktla fikri ayrıca işarələ.\n\n## Addım-addım icra\n1. Ən azı beş etibarlı mənbə tap.\n2. Nəşr tarixlərini yoxla.\n3. Faktla fikri ayrıca işarələ.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAnnotated sources. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nFind five credible sources ;  Check dates ;  Separate facts from opinions.\n\n## Step-by-step\n1. Find five credible sources.\n2. Check dates.\n3. Separate facts from opinions.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAnnotated source list. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nƏn azı beş etibarlı mənbə tap ;  Nəşr tarixlərini yoxla ;  Faktla fikri ayrıca işarələ.\n\n[[EN]]\nFind five credible sources ;  Check dates ;  Separate facts from opinions.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Source Research\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** Rəsmi universitet və şirkət saytı daxil olmaqla 5 mənbənin tarixini və etibarlılığını yoxla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-2. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Ən azı beş etibarlı mənbə tap. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Nəşr tarixlərini yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Faktla fikri ayrıca işarələ. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Rəsmi universitet və şirkət saytı daxil olmaqla 5 mənbənin tarixini və etibarlılığını yoxla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Annotated sources. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nRəsmi universitet və şirkət saytı daxil olmaqla 5 mənbənin tarixini və etibarlılığını yoxla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Annotated sources.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Source Research\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Verify dates and credibility of five sources including official university or company pages.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-2. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Find five credible sources. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Check dates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Separate facts from opinions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Verify dates and credibility of five sources including official university or company pages. Document what worked and any limitations.\n7. Complete the main artifact: Annotated source list. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nVerify dates and credibility of five sources including official university or company pages.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Annotated source list.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nSource Research: Ən azı beş etibarlı mənbə tap. Nəşr tarixlərini yoxla. Faktla fikri ayrıca işarələ. Pulsuz alətlər: Google Docs, Google Sheets. Nəticə: Annotated sources.\n\n[[EN]]\nSource Research: Find five credible sources. Check dates. Separate facts from opinions. Free tools: Google Docs, Google Sheets. Output: Annotated source list."},{"slug":"talora-content-writing-2026","task_number":3,"title":"Headline and Structure","old_instructions":"[[AZ]]\n## Məqsəd\nBeş başlıq alternativi yaz ;  H1/H2 strukturu hazırla ;  Oxu niyyətini nəzərə al.\n\n## Addım-addım icra\n1. Beş başlıq alternativi yaz.\n2. H1/H2 strukturu hazırla.\n3. Oxu niyyətini nəzərə al.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nHeadline and outline sheet. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDraft five headlines ;  Create H1/H2 outline ;  Align structure with search intent.\n\n## Step-by-step\n1. Draft five headlines.\n2. Create H1/H2 outline.\n3. Align structure with search intent.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nHeadline and outline sheet. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBeş başlıq alternativi yaz ;  H1/H2 strukturu hazırla ;  Oxu niyyətini nəzərə al.\n\n[[EN]]\nDraft five headlines ;  Create H1/H2 outline ;  Align structure with search intent.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Headline and Structure\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** 'Təcrübəyə hazırlaşmaq üçün 7 addım' mövzusunun 5 başlıq variantını müqayisə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-3. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Beş başlıq alternativi yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. H1/H2 strukturu hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Oxu niyyətini nəzərə al. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Təcrübəyə hazırlaşmaq üçün 7 addım' mövzusunun 5 başlıq variantını müqayisə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Headline and outline sheet. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Təcrübəyə hazırlaşmaq üçün 7 addım' mövzusunun 5 başlıq variantını müqayisə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Headline and outline sheet.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Headline and Structure\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Compare five non-clickbait headlines about preparing for internships.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-3. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Draft five headlines. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Create H1/H2 outline. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Align structure with search intent. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare five non-clickbait headlines about preparing for internships. Document what worked and any limitations.\n7. Complete the main artifact: Headline and outline sheet. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare five non-clickbait headlines about preparing for internships.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Headline and outline sheet.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nHeadline and Structure: Beş başlıq alternativi yaz. H1/H2 strukturu hazırla. Oxu niyyətini nəzərə al. Pulsuz alətlər: Google Docs. Nəticə: Headline and outline sheet.\n\n[[EN]]\nHeadline and Structure: Draft five headlines. Create H1/H2 outline. Align structure with search intent. Free tools: Google Docs. Output: Headline and outline sheet."},{"slug":"talora-content-writing-2026","task_number":4,"title":"Long-form Article","old_instructions":"[[AZ]]\n## Məqsəd\n800-1000 sözlük orijinal məqalə yaz ;  Faktları mənbə ilə bağla ;  Girişi və nəticəni redaktə et.\n\n## Addım-addım icra\n1. 800-1000 sözlük orijinal məqalə yaz.\n2. Faktları mənbə ilə bağla.\n3. Girişi və nəticəni redaktə et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nPublished-ready article draft. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite an original 800–1000 word article ;  Cite factual claims ;  Edit opening and conclusion.\n\n## Step-by-step\n1. Write an original 800–1000 word article.\n2. Cite factual claims.\n3. Edit opening and conclusion.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nPublication-ready draft. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\n800-1000 sözlük orijinal məqalə yaz ;  Faktları mənbə ilə bağla ;  Girişi və nəticəni redaktə et.\n\n[[EN]]\nWrite an original 800–1000 word article ;  Cite factual claims ;  Edit opening and conclusion.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Long-form Article\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** 800–1000 sözlük CV, portfolio, müraciət və müsahibə bölməli məqalə yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-4. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. 800-1000 sözlük orijinal məqalə yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Faktları mənbə ilə bağla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Girişi və nəticəni redaktə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 800–1000 sözlük CV, portfolio, müraciət və müsahibə bölməli məqalə yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Published-ready article draft. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n800–1000 sözlük CV, portfolio, müraciət və müsahibə bölməli məqalə yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Published-ready article draft.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Long-form Article\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Write an 800–1,000 word guide on CVs, portfolios, applications and interviews.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-4. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write an original 800–1000 word article. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Cite factual claims. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Edit opening and conclusion. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Write an 800–1,000 word guide on CVs, portfolios, applications and interviews. Document what worked and any limitations.\n7. Complete the main artifact: Publication-ready draft. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nWrite an 800–1,000 word guide on CVs, portfolios, applications and interviews.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Publication-ready draft.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLong-form Article: 800-1000 sözlük orijinal məqalə yaz. Faktları mənbə ilə bağla. Girişi və nəticəni redaktə et. Pulsuz alətlər: Google Docs. Nəticə: Published-ready article draft.\n\n[[EN]]\nLong-form Article: Write an original 800–1000 word article. Cite factual claims. Edit opening and conclusion. Free tools: Google Docs. Output: Publication-ready draft."},{"slug":"talora-content-writing-2026","task_number":5,"title":"Microcopy and Social Captions","old_instructions":"[[AZ]]\n## Məqsəd\nBir mövzunu üç platformaya uyğunlaşdır ;  Uzunluğu və tonu dəyiş ;  İki CTA variantı yaz.\n\n## Addım-addım icra\n1. Bir mövzunu üç platformaya uyğunlaşdır.\n2. Uzunluğu və tonu dəyiş.\n3. İki CTA variantı yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nSocial copy pack. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nAdapt one topic for three platforms ;  Adjust length and tone ;  Test two CTAs.\n\n## Step-by-step\n1. Adapt one topic for three platforms.\n2. Adjust length and tone.\n3. Test two CTAs.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSocial copy pack. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBir mövzunu üç platformaya uyğunlaşdır ;  Uzunluğu və tonu dəyiş ;  İki CTA variantı yaz.\n\n[[EN]]\nAdapt one topic for three platforms ;  Adjust length and tone ;  Test two CTAs.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Microcopy and Social Captions\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** Eyni məqalədən LinkedIn, Instagram və newsletter üçün fərqli 3 qısa mətn çıxart.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Canva Free** — https://www.canva.com. Yalnız Free elementlərdən istifadə et, nəticəni PNG/PDF ixrac et; Pro elementə pul vermə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-5. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Bir mövzunu üç platformaya uyğunlaşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Uzunluğu və tonu dəyiş. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İki CTA variantı yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Eyni məqalədən LinkedIn, Instagram və newsletter üçün fərqli 3 qısa mətn çıxart. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Social copy pack. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nEyni məqalədən LinkedIn, Instagram və newsletter üçün fərqli 3 qısa mətn çıxart.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Social copy pack.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Microcopy and Social Captions\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Adapt one article into distinct LinkedIn, Instagram and newsletter captions.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Canva Free** — https://www.canva.com. Use only Free elements, export PNG/PDF and avoid Pro assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-5. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Adapt one topic for three platforms. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Adjust length and tone. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Test two CTAs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Adapt one article into distinct LinkedIn, Instagram and newsletter captions. Document what worked and any limitations.\n7. Complete the main artifact: Social copy pack. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nAdapt one article into distinct LinkedIn, Instagram and newsletter captions.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Social copy pack.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nMicrocopy and Social Captions: Bir mövzunu üç platformaya uyğunlaşdır. Uzunluğu və tonu dəyiş. İki CTA variantı yaz. Pulsuz alətlər: Google Docs, Canva Free. Nəticə: Social copy pack.\n\n[[EN]]\nMicrocopy and Social Captions: Adapt one topic for three platforms. Adjust length and tone. Test two CTAs. Free tools: Google Docs, Canva Free. Output: Social copy pack."},{"slug":"talora-content-writing-2026","task_number":6,"title":"Brand Voice Guide","old_instructions":"[[AZ]]\n## Məqsəd\nBrend üçün üç ton prinsipi seç ;  Do/don't nümunələri yaz ;  Mətni eyni tonda redaktə et.\n\n## Addım-addım icra\n1. Brend üçün üç ton prinsipi seç.\n2. Do/don't nümunələri yaz.\n3. Mətni eyni tonda redaktə et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nVoice and style guide. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nDefine three tone principles ;  Write do/don't examples ;  Edit copy for consistency.\n\n## Step-by-step\n1. Define three tone principles.\n2. Write do/don't examples.\n3. Edit copy for consistency.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nVoice and style guide. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nBrend üçün üç ton prinsipi seç ;  Do/don't nümunələri yaz ;  Mətni eyni tonda redaktə et.\n\n[[EN]]\nDefine three tone principles ;  Write do/don't examples ;  Edit copy for consistency.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Brand Voice Guide\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** Talora üçün aydın və tələbəyə yaxın ton, do/don't misalları hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-6. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Brend üçün üç ton prinsipi seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Do/don't nümunələri yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Mətni eyni tonda redaktə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Talora üçün aydın və tələbəyə yaxın ton, do/don't misalları hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Voice and style guide. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nTalora üçün aydın və tələbəyə yaxın ton, do/don't misalları hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Voice and style guide.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Brand Voice Guide\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Create a student-friendly Talora voice guide with do/don't examples.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-6. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Define three tone principles. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Write do/don't examples. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Edit copy for consistency. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create a student-friendly Talora voice guide with do/don't examples. Document what worked and any limitations.\n7. Complete the main artifact: Voice and style guide. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate a student-friendly Talora voice guide with do/don't examples.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Voice and style guide.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nBrand Voice Guide: Brend üçün üç ton prinsipi seç. Do/don't nümunələri yaz. Mətni eyni tonda redaktə et. Pulsuz alətlər: Google Docs. Nəticə: Voice and style guide.\n\n[[EN]]\nBrand Voice Guide: Define three tone principles. Write do/don't examples. Edit copy for consistency. Free tools: Google Docs. Output: Voice and style guide."},{"slug":"talora-content-writing-2026","task_number":7,"title":"Fact-check and Copyright","old_instructions":"[[AZ]]\n## Məqsəd\nMəqalədə on iddianı yoxla ;  Sitat və şəkil istifadəsini audit et ;  Müəlliflik risklərini qeyd et.\n\n## Addım-addım icra\n1. Məqalədə on iddianı yoxla.\n2. Sitat və şəkil istifadəsini audit et.\n3. Müəlliflik risklərini qeyd et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFact-check log. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nVerify ten claims ;  Audit quotes and visual rights ;  Record copyright risks.\n\n## Step-by-step\n1. Verify ten claims.\n2. Audit quotes and visual rights.\n3. Record copyright risks.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nFact-check log. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMəqalədə on iddianı yoxla ;  Sitat və şəkil istifadəsini audit et ;  Müəlliflik risklərini qeyd et.\n\n[[EN]]\nVerify ten claims ;  Audit quotes and visual rights ;  Record copyright risks.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Fact-check and Copyright\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** Məqalədə 10 iddianı yoxla, şəkil üçün istifadəyə icazə qeyd et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-7. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Məqalədə on iddianı yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Sitat və şəkil istifadəsini audit et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Müəlliflik risklərini qeyd et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Məqalədə 10 iddianı yoxla, şəkil üçün istifadəyə icazə qeyd et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Fact-check log. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMəqalədə 10 iddianı yoxla, şəkil üçün istifadəyə icazə qeyd et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Fact-check log.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Fact-check and Copyright\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Fact-check ten claims and document usage rights for images.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-7. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Verify ten claims. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Audit quotes and visual rights. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Record copyright risks. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Fact-check ten claims and document usage rights for images. Document what worked and any limitations.\n7. Complete the main artifact: Fact-check log. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nFact-check ten claims and document usage rights for images.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Fact-check log.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nFact-check and Copyright: Məqalədə on iddianı yoxla. Sitat və şəkil istifadəsini audit et. Müəlliflik risklərini qeyd et. Pulsuz alətlər: Google Docs, Google Sheets. Nəticə: Fact-check log.\n\n[[EN]]\nFact-check and Copyright: Verify ten claims. Audit quotes and visual rights. Record copyright risks. Free tools: Google Docs, Google Sheets. Output: Fact-check log."},{"slug":"talora-content-writing-2026","task_number":8,"title":"Newsletter Edition","old_instructions":"[[AZ]]\n## Məqsəd\nMövzu sətri və preheader yaz ;  E-poçt məzmununu bölmələrə ayır ;  Oxunaqlıq və icazəli linkləri yoxla.\n\n## Addım-addım icra\n1. Mövzu sətri və preheader yaz.\n2. E-poçt məzmununu bölmələrə ayır.\n3. Oxunaqlıq və icazəli linkləri yoxla.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nNewsletter mockup. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nWrite subject and preheader ;  Structure newsletter sections ;  Verify readability and consent links.\n\n## Step-by-step\n1. Write subject and preheader.\n2. Structure newsletter sections.\n3. Verify readability and consent links.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nNewsletter draft. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nMövzu sətri və preheader yaz ;  E-poçt məzmununu bölmələrə ayır ;  Oxunaqlıq və icazəli linkləri yoxla.\n\n[[EN]]\nWrite subject and preheader ;  Structure newsletter sections ;  Verify readability and consent links.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Newsletter Edition\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** 'Bu həftənin 3 təcrübə tövsiyəsi' mövzulu mock newsletter hazırlayıb göndərmə.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-8. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Mövzu sətri və preheader yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. E-poçt məzmununu bölmələrə ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Oxunaqlıq və icazəli linkləri yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 'Bu həftənin 3 təcrübə tövsiyəsi' mövzulu mock newsletter hazırlayıb göndərmə. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Newsletter mockup. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n'Bu həftənin 3 təcrübə tövsiyəsi' mövzulu mock newsletter hazırlayıb göndərmə.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Newsletter mockup.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Newsletter Edition\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Draft a three-tip newsletter mockup without sending it.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-8. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Write subject and preheader. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Structure newsletter sections. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Verify readability and consent links. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Draft a three-tip newsletter mockup without sending it. Document what worked and any limitations.\n7. Complete the main artifact: Newsletter draft. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDraft a three-tip newsletter mockup without sending it.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Newsletter draft.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nNewsletter Edition: Mövzu sətri və preheader yaz. E-poçt məzmununu bölmələrə ayır. Oxunaqlıq və icazəli linkləri yoxla. Pulsuz alətlər: Google Docs. Nəticə: Newsletter mockup.\n\n[[EN]]\nNewsletter Edition: Write subject and preheader. Structure newsletter sections. Verify readability and consent links. Free tools: Google Docs. Output: Newsletter draft."},{"slug":"talora-content-writing-2026","task_number":9,"title":"Accessibility Edit","old_instructions":"[[AZ]]\n## Məqsəd\nSadə dil və başlıqları yoxla ;  Alt mətn və link adlarını yaxşılaşdır ;  Müxtəlif oxucu ehtiyaclarına uyğunlaşdır.\n\n## Addım-addım icra\n1. Sadə dil və başlıqları yoxla.\n2. Alt mətn və link adlarını yaxşılaşdır.\n3. Müxtəlif oxucu ehtiyaclarına uyğunlaşdır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nAccessible content checklist. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nReview plain language and headings ;  Improve alt text and link labels ;  Consider accessibility needs.\n\n## Step-by-step\n1. Review plain language and headings.\n2. Improve alt text and link labels.\n3. Consider accessibility needs.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nAccessibility checklist. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nSadə dil və başlıqları yoxla ;  Alt mətn və link adlarını yaxşılaşdır ;  Müxtəlif oxucu ehtiyaclarına uyğunlaşdır.\n\n[[EN]]\nReview plain language and headings ;  Improve alt text and link labels ;  Consider accessibility needs.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Accessibility Edit\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** Başlıq sırası, alt text, sadə dil və təsviri link adı üzrə məqaləni redaktə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-9. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Sadə dil və başlıqları yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Alt mətn və link adlarını yaxşılaşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Müxtəlif oxucu ehtiyaclarına uyğunlaşdır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Başlıq sırası, alt text, sadə dil və təsviri link adı üzrə məqaləni redaktə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Accessible content checklist. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nBaşlıq sırası, alt text, sadə dil və təsviri link adı üzrə məqaləni redaktə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Accessible content checklist.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Accessibility Edit\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Edit the article for heading hierarchy, alt text, plain language and useful links.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-9. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Review plain language and headings. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Improve alt text and link labels. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Consider accessibility needs. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Edit the article for heading hierarchy, alt text, plain language and useful links. Document what worked and any limitations.\n7. Complete the main artifact: Accessibility checklist. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nEdit the article for heading hierarchy, alt text, plain language and useful links.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Accessibility checklist.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nAccessibility Edit: Sadə dil və başlıqları yoxla. Alt mətn və link adlarını yaxşılaşdır. Müxtəlif oxucu ehtiyaclarına uyğunlaşdır. Pulsuz alətlər: Google Docs. Nəticə: Accessible content checklist.\n\n[[EN]]\nAccessibility Edit: Review plain language and headings. Improve alt text and link labels. Consider accessibility needs. Free tools: Google Docs. Output: Accessibility checklist."},{"slug":"talora-content-writing-2026","task_number":10,"title":"Editorial Portfolio","old_instructions":"[[AZ]]\n## Məqsəd\nƏn yaxşı dörd nümunəni seç ;  Dəyişikliklər üçün before-after qeyd et ;  Mənbə və istifadəyə icazələri göstər.\n\n## Addım-addım icra\n1. Ən yaxşı dörd nümunəni seç.\n2. Dəyişikliklər üçün before-after qeyd et.\n3. Mənbə və istifadəyə icazələri göstər.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nWriting portfolio. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSelect four writing samples ;  Document before-and-after edits ;  Include source and permission notes.\n\n## Step-by-step\n1. Select four writing samples.\n2. Document before-and-after edits.\n3. Include source and permission notes.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nWriting portfolio. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nƏn yaxşı dörd nümunəni seç ;  Dəyişikliklər üçün before-after qeyd et ;  Mənbə və istifadəyə icazələri göstər.\n\n[[EN]]\nSelect four writing samples ;  Document before-and-after edits ;  Include source and permission notes.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Editorial Portfolio\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Məzmun oxucunun konkret problemini həll etməli və faktları mənbə ilə göstərməlidir.\n**Nümunə situasiya:** 4 ən yaxşı yazı üçün məqsəd, mənbə və before/after redaktə nümunəsi hazırla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n- **GitHub Free** — https://github.com. Pulsuz repo və README yarat; token, şəxsi məlumat və lisenziyasız material yükləmə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Content Writing / Task-10. Əvvəlki tapşırıqların nəticəsi varsa onlardan istifadə et; yoxdursa 5 sintetik nümunə sətri hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Ən yaxşı dörd nümunəni seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Dəyişikliklər üçün before-after qeyd et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Mənbə və istifadəyə icazələri göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 4 ən yaxşı yazı üçün məqsəd, mənbə və before/after redaktə nümunəsi hazırla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Writing portfolio. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n4 ən yaxşı yazı üçün məqsəd, mənbə və before/after redaktə nümunəsi hazırla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Writing portfolio.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Sitat və şəkillərin istifadəsinə icazəni yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Editorial Portfolio\nThis practical assignment is designed for beginners. Writing should answer a real reader question using verifiable sources.\n**Example scenario:** Create a four-piece writing portfolio with sources and before/after edits.\n\n## Free tools and platforms\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n- **GitHub Free** — https://github.com. Create a free repo and README; never upload keys, private data or unlicensed assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Content Writing / Task-10. Reuse your earlier fictional artifacts or create five sample records.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Select four writing samples. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Document before-and-after edits. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Include source and permission notes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create a four-piece writing portfolio with sources and before/after edits. Document what worked and any limitations.\n7. Complete the main artifact: Writing portfolio. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate a four-piece writing portfolio with sources and before/after edits.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Writing portfolio.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Credit quotations and verify image permissions.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nEditorial Portfolio: Ən yaxşı dörd nümunəni seç. Dəyişikliklər üçün before-after qeyd et. Mənbə və istifadəyə icazələri göstər. Pulsuz alətlər: Google Docs, GitHub Free. Nəticə: Writing portfolio.\n\n[[EN]]\nEditorial Portfolio: Select four writing samples. Document before-and-after edits. Include source and permission notes. Free tools: Google Docs, GitHub Free. Output: Writing portfolio."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-content-writing-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-content-writing-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-content-writing-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-content-writing-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-content-writing-2026: %',matched; END IF;
END; $verify$;
COMMIT;